import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import register_hook, get_account_dict, get_stock_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
REBALANCE_DAYS = 10
MIN_W, MAX_W = 0.02, 0.14
last_date = None


def rank_factor(values):
    out = {s: 0.5 for s in UNIVERSE}
    valid = sorted((s, float(v)) for s, v in values.items() if np.isfinite(v))
    n = len(valid)
    if n:
        for i, (s, _) in enumerate(valid):
            out[s] = (i + 1.0) / n
    return out


def project(raw):
    # Stable bounded simplex projection for the 15-asset, no-cash contract.
    w = {s: max(1e-9, float(raw.get(s, 0.0))) for s in UNIVERSE}
    for _ in range(50):
        z = sum(w.values())
        w = {s: x / z for s, x in w.items()}
        low = [s for s in UNIVERSE if w[s] < MIN_W]
        high = [s for s in UNIVERSE if w[s] > MAX_W]
        if not low and not high:
            break
        fixed = set(low + high)
        for s in low: w[s] = MIN_W
        for s in high: w[s] = MAX_W
        rem = 1.0 - sum(w[s] for s in fixed)
        free = [s for s in UNIVERSE if s not in fixed]
        if not free: break
        zfree = sum(w[s] for s in free) or 1.0
        for s in free: w[s] = rem * w[s] / zfree
    z = sum(w.values())
    return {s: w[s] / z for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global last_date
    account = get_account_dict()
    data = {}
    for s in UNIVERSE:
        df = get_stock_daily_data(symbol=s, days=90)
        if df is None or len(df) < 25: continue
        df = df.sort_values("date").reset_index(drop=True)
        c = np.asarray(df["close"], dtype=float)
        r = c[1:] / np.maximum(c[:-1], 1e-12) - 1.0
        data[s] = (c, r, str(df.iloc[-1]["date"]))
    if len(data) < 12: return
    decision = max(v[2] for v in data.values())
    if last_date is not None:
        try:
            elapsed = (np.datetime64(decision) - np.datetime64(last_date)) / np.timedelta64(1, "D")
            if elapsed < REBALANCE_DAYS: return
        except Exception: return

    ret5 = {s: c[-1] / c[-6] - 1.0 for s, (c, r, _) in data.items() if len(c) >= 7}
    median5 = float(np.median(list(ret5.values())))
    factors = {
        "peer_median_leadlag_5d": {s: v - median5 for s, v in ret5.items()},
        "short_term_reversal_5d": {s: -v for s, v in ret5.items()},
        "miner_2_risk_adjusted_momentum_20d": {
            s: (c[-1] / c[-21] - 1.0) / max(float(np.std(r[-20:])), 0.008)
            for s, (c, r, _) in data.items() if len(c) >= 22
        },
        "miner_3_intraday_reversal_1d": {s: -r[-1] for s, (c, r, _) in data.items() if len(r) >= 1},
        "miner_2_short_reversal_3d": {s: -(c[-1] / c[-4] - 1.0) for s, (c, r, _) in data.items() if len(c) >= 5},
    }
    ensemble_path = Path(__file__).parent / "factors" / "factor_ensemble.json"
    try:
        ensemble = json.loads(ensemble_path.read_text())
        selected = ensemble.get("selected_factors", [])[:10]
    except (OSError, ValueError, TypeError):
        return
    scores = {s: 0.0 for s in UNIVERSE}
    for item in selected:
        fid, wt, direction = item.get("factor_id"), float(item.get("weight", 0.0)), float(item.get("direction", 1))
        if fid in factors:
            rr = rank_factor(factors[fid])
            for s in UNIVERSE: scores[s] += wt * direction * rr[s]
    # Bullish but choppy: retain broad exposure and modestly reward defensive assets.
    if "SPX" in data:
        spx = data["SPX"][0]
        if spx[-1] < spx[-21] or spx[-1] < spx[-6]:
            for s in ("XAU", "US10Y", "CN10Y"): scores[s] += 0.10
            for s in ("BTC", "ETH", "WTI"): scores[s] -= 0.04
    vols = {s: max(float(np.std(r[-20:])), 0.008) for s, (c, r, _) in data.items()}
    medvol = float(np.median(list(vols.values())))
    raw = {s: max(0.01, scores[s]) * (0.85 + 0.15 * medvol / vols.get(s, medvol)) for s in UNIVERSE}
    weights = project(raw)
    mean, std = float(np.mean(list(scores.values()))), float(np.std(list(scores.values())))
    forecast = {s: 0.01 * (scores[s] - mean) / max(std, 1e-9) for s in UNIVERSE}
    factor_ids = [str(x.get("factor_id")) for x in selected if x.get("factor_id") in factors]
    rebalance_to_weights(weights, forecast_returns=forecast, factor_ids=factor_ids[:10], horizon_days=10)
    last_date = decision

