import numpy as np
from alphacrafter.sim.utils import (
    register_hook, get_account_dict, get_stock_daily_data, rebalance_to_weights,
)

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
FACTOR_IDS = [
    "miner_2_range_efficiency_20d", "peer_median_leadlag_5d",
    "miner_2_risk_adjusted_momentum_20d", "miner_3_20271005_relative_reversal_5d",
    "miner_2_short_reversal_3d", "short_term_reversal_5d",
]
FACTOR_WEIGHTS = [0.22, 0.20, 0.18, 0.16, 0.14, 0.10]
DIRECTIONS = [1, 1, 1, 1, 1, 1]
REBALANCE_DAYS = 10
last_date = None


def ranks(x):
    out = {s: 0.5 for s in UNIVERSE}
    good = sorted((s, float(v)) for s, v in x.items() if np.isfinite(v))
    n = len(good)
    if n > 1:
        for i, (s, _) in enumerate(good):
            out[s] = (i + 1.0) / n
    return out


def bounded(raw):
    # Sixteen? No: exactly 15 assets, full investment, fractional weights.
    w = {s: max(0.0, float(raw.get(s, 0.0))) for s in UNIVERSE}
    # A 15-name universe supports broad diversification; cap concentration.
    w = {s: max(0.02, min(0.14, v)) for s, v in w.items()}
    for _ in range(30):
        free = [s for s in UNIVERSE if 0.020001 < w[s] < 0.139999]
        fixed = sum(w[s] for s in UNIVERSE if s not in free)
        if not free:
            break
        rem = max(0.0, 1.0 - fixed)
        total = sum(w[s] for s in free) or 1.0
        for s in free:
            w[s] = rem * w[s] / total
        w = {s: max(0.02, min(0.14, v)) for s, v in w.items()}
    z = sum(w.values())
    return {s: w[s] / z for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global last_date
    account = get_account_dict()
    market = {}
    for s in UNIVERSE:
        df = get_stock_daily_data(symbol=s, days=90)
        if df is None or len(df) < 30:
            continue
        df = df.sort_values("date").reset_index(drop=True)
        c = np.asarray(df["close"], dtype=float)
        r = c[1:] / np.maximum(c[:-1], 1e-12) - 1.0
        market[s] = (c, r, str(df.iloc[-1]["date"]))
    if len(market) < 12:
        return
    decision = max(v[2] for v in market.values())
    if last_date is not None:
        try:
            gap = (np.datetime64(decision, "D") - np.datetime64(last_date, "D")) / np.timedelta64(1, "D")
            if gap < REBALANCE_DAYS:
                return
        except Exception:
            return

    five = {s: c[-1] / max(c[-6], 1e-12) - 1.0 for s, (c, _, _) in market.items()}
    median5 = float(np.median(list(five.values())))
    factors = [dict() for _ in FACTOR_IDS]
    for s, (c, r, _) in market.items():
        v20 = max(float(np.std(r[-20:])), 0.008)
        ret20 = c[-1] / max(c[-21], 1e-12) - 1.0
        # Proxies preserve the supplied factor directions and are all backward-looking.
        factors[0][s] = abs(ret20) / (float(np.sum(np.abs(r[-20:]))) + 1e-12)
        factors[1][s] = five[s] - median5
        factors[2][s] = ret20 / v20
        factors[3][s] = -(five[s] - median5)
        factors[4][s] = -float(np.mean(r[-3:]))
        factors[5][s] = -float(np.mean(r[-5:]))
    rr = [ranks(x) for x in factors]
    score = {s: sum(ww * q[s] for ww, q in zip(FACTOR_WEIGHTS, rr)) for s in UNIVERSE}

    # Risk-off correction: remain fully invested but rotate toward tradable defensives.
    if "SPX" in market:
        c, r, _ = market["SPX"]
        if c[-1] < c[-21] and float(np.std(r[-20:])) > 0.012:
            for s in ("XAU", "US10Y", "CN10Y"):
                score[s] += 0.10
            for s in ("BTC", "ETH", "WTI"):
                score[s] = max(0.01, score[s] - 0.05)

    invvol = {s: 1.0 / max(float(np.std(market[s][1][-20:])), 0.008) for s in market}
    mean_iv = float(np.mean(list(invvol.values())))
    raw = {s: max(0.01, score[s]) * (0.85 + 0.15 * invvol.get(s, mean_iv) / mean_iv) for s in UNIVERSE}
    weights = bounded(raw)
    mean_score = float(np.mean(list(score.values())))
    sd = max(float(np.std(list(score.values()))), 1e-12)
    forecast_returns = {s: float(0.01 * (score[s] - mean_score) / sd) for s in UNIVERSE}
    rebalance_to_weights(weights, forecast_returns=forecast_returns, factor_ids=FACTOR_IDS, horizon_days=10)
    last_date = decision

