    return out


def make_weights(score):
    # Full investment, deliberately broad in a 15-name universe.
    raw = {s: max(0.02, score.get(s, 0.5)) for s in UNIVERSE}
    total = sum(raw.values())
    w = {s: raw[s] / total for s in UNIVERSE}
    # Bound concentration and redistribute excess until stable.
    for _ in range(20):
        excess = sum(max(0.0, x - 0.13) for x in w.values())
        if excess < 1e-10:
            break
        free = [s for s in UNIVERSE if w[s] < 0.13 - 1e-10]
        for s in UNIVERSE:
            if w[s] > 0.13:
                w[s] = 0.13
        base = sum(w[s] for s in free)
        if base <= 0:
            break
        for s in free:
            w[s] += excess * w[s] / base
