def ranks(values):
    valid = sorted((s, float(v)) for s, v in values.items() if np.isfinite(v))
    out = {s: 0.5 for s in UNIVERSE}
    if len(valid) > 1:
        for i, (s, _) in enumerate(valid):
            out[s] = (i + 1.0) / len(valid)
    return out


def bounded_weights(score):
    # Broad, defensive full investment is more robust than a concentrated top-N
    # in this deliberately small cross-asset universe.
    w = {s: max(0.025, float(score.get(s, 0.5))) for s in UNIVERSE}
    z = sum(w.values())
    w = {s: x / z for s, x in w.items()}
    for _ in range(30):
        excess = sum(max(0.0, x - 0.13) for x in w.values())
        if excess < 1e-10:
            break
        capped = [s for s in UNIVERSE if w[s] >= 0.13 - 1e-10]
        free = [s for s in UNIVERSE if s not in capped]
        for s in capped:
            w[s] = min(w[s], 0.13)
        base = sum(w[s] for s in free)
        if base <= 0:
            break
        for s in free:
            w[s] += excess * w[s] / base
    w = {s: max(0.025, x) for s, x in w.items()}
    z = sum(w.values())
    return {s: float(x / z) for s, x in w.items()}


