    "miner_3_20271102_volscaled_relative_reversal_5d", "short_term_reversal_5d",
    "miner_2_20271103_volume_pressure_reversal_3d"
]
FACTOR_WEIGHTS = [0.20, 0.18, 0.17, 0.14, 0.13, 0.10, 0.08]
last_decision = None


def ranks(x):
    good = sorted((s, float(v)) for s, v in x.items() if np.isfinite(v))
    out = {s: 0.5 for s in UNIVERSE}
    if len(good) > 1:
        for i, (s, _) in enumerate(good):
            out[s] = (i + 1.0) / len(good)
    return out


def weights_from_score(score):
    lo, hi = 0.025, 0.13
    raw = np.array([max(0.0, score[s]) for s in UNIVERSE], dtype=float)
    w = raw / max(raw.sum(), 1e-12)
    # Project onto the complete long-only bounded simplex.
    for _ in range(20):
        fixed = (w < lo) | (w > hi)
        old = w.copy()
        w = np.clip(w, lo, hi)
        free = ~fixed
        residual = 1.0 - w[~free].sum()
        if free.any():
            base = old[free].clip(lo, hi)
            w[free] = base / max(base.sum(), 1e-12) * residual
        if np.max(np.abs(w - old)) < 1e-10:
            break
    w = np.clip(w, lo, hi)
    return {s: float(v / w.sum()) for s, v in zip(UNIVERSE, w)}


@register_hook
def cross_asset_strategy():
    global last_decision
    data = {}
    for s in UNIVERSE:
        df = get_stock_daily_data(symbol=s, days=100)
        if df is None or len(df) < 35:
            continue
