        c = np.asarray(df["close"], dtype=float)
        if np.any(~np.isfinite(c[-30:])) or np.any(c[-30:] <= 0):
            continue
        data[s] = (c, str(df.iloc[-1]["date"]))
    if len(data) < 12:
        return
    decision = max(v[1] for v in data.values())
    if last_decision is not None:
        try:
            if (np.datetime64(decision) - np.datetime64(last_decision)) / np.timedelta64(1, "D") < 10:
                return
        except Exception:
            return

    ret5 = {s: c[-1] / c[-6] - 1.0 for s, (c, _) in data.items()}
    peer = float(np.median(list(ret5.values())))
    f = [{} for _ in FACTOR_IDS]
    for s, (c, _) in data.items():
        d = c[1:] / np.maximum(c[:-1], 1e-12) - 1.0
        d20 = d[-20:]
        vol = max(float(np.std(d20)), 0.008)
        r20 = c[-1] / c[-21] - 1.0
        # Causal price proxies aligned to the persisted factor directions.
        f[0][s] = ret5[s] - peer
        f[1][s] = abs(r20) / max(float(np.sum(np.abs(d20))), 1e-8)
        f[2][s] = r20 / vol
        f[3][s] = min(r20, 0.0) / vol
        f[4][s] = -(ret5[s] - peer) / vol
        f[5][s] = -float(np.mean(d[-5:]))
        f[6][s] = -float(np.mean(d[-3:]))
    rr = [ranks(x) for x in f]
    score = {s: sum(a * r[s] for a, r in zip(FACTOR_WEIGHTS, rr)) for s in UNIVERSE}

    # High-risk bearish regime: remain fully invested, but migrate toward
    # defensive tradable benchmarks rather than using a cash sleeve.
    if "SPX" in data:
        c = data["SPX"][0]
        d = c[1:] / np.maximum(c[:-1], 1e-12) - 1.0
        if c[-1] < c[-21] or np.std(d[-20:]) > 0.018:
            for s in ("XAU", "US10Y", "CN10Y"):
                score[s] += 0.10
            for s in ("BTC", "ETH", "WTI"):
                score[s] *= 0.75

    target = weights_from_score(score)
    a = np.array([score[s] for s in UNIVERSE], dtype=float)
    z = (a - a.mean()) / max(float(a.std()), 1e-12)
    forecast_returns = {s: float(0.008 * z[i]) for i, s in enumerate(UNIVERSE)}
    rebalance_to_weights(target, forecast_returns=forecast_returns,
                         factor_ids=FACTOR_IDS, horizon_days=10)
    last_decision = decision

