            a = b
            break
        free = (b > 0.030001) & (b < 0.139999)
        rem = 1.0 - b[~free].sum()
        if free.any() and rem > 0:
            b[free] *= rem / b[free].sum()
        a = b
    a = np.clip(a, 0.03, 0.14)
